#include<bits/stdc++.h>
#define pii pair<int,int>
#define fi first
#define se second
#define int long long
#define pb push_back
#define mod 1000000007
#define pll pair<long long,long long>
using namespace std;
long long power(long long a,long long b){
    long long ans=1;
    while(b>0){
        if(b&1){ans=(ans*a)%mod;}
                a=(a*a)%mod;
                b>>=1;
        }
    return ans;

}
bool prime(int n){
    for(int i=2;i*i<=n;i++){
        if(n%i==0)return false;
    }
    return true;
}
int32_t main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    string s;
    cin>>s;
    int n=s.size();
    string s1;
    int i=1;
    s1.pb(s[0]);
    while(i<n){
        if(i<n-3&&s[i]=='d'&&s[i+1]=='o'&&s[i+2]=='t'){
            s1.pb('.');
            i+=3;
        }
        else{
            s1.pb(s[i]);
            i++;
        }
    }
    int m=s1.size();
    i=1;
    string s2;
    s2.pb(s1[0]);
    bool b=true;
    while(i<m){
        if(b&&i<m-2&&s1[i]=='a'&&s1[i+1]=='t'){
           s2.pb('@');
           i+=2;
           b=false;
        }
        else{
            s2.pb(s1[i]);
            i++;
        }
    }
    cout<<s2;
    return 0;
}    

